    85      // A recoded DNG might be split up into tiles of self contained LJpeg
    86      // blobs. The tiles at the bottom and the right may extend beyond the
    87      // dimension of the raw image buffer. The excessive content has to be
    88      // ignored. For y, we can simply stop decoding when we reached the border.
    89      if (destY >= static_cast<unsigned>(mRaw->dim.y))
    90        break;
    91
    92      auto dest =
    93          reinterpret_cast<ushort16*>(mRaw->getDataUncropped(offX, destY));
    94
    95      copy_n(predNext, N_COMP, pred.data());
    96      // the predictor for the next line is the start of this line
    97      predNext = dest;
    98
    99      unsigned width = min(frame.w,
   100                           (mRaw->dim.x - offX) / (N_COMP / mRaw->getCpp()));
   101
   102      // For x, we first process all pixels within the image buffer ...
   103      for (unsigned x = 0; x < width; ++x) {
   104        unroll_loop<N_COMP>([&](int i) {
   105          *dest++ = pred[i] += ht[i]->decodeNext(bitStream);
   106        });
   107      }
   108      // ... and discard the rest.
   109      for (unsigned x = width; x < frame.w; ++x) {
   110        unroll_loop<N_COMP>([&](int i) {
   111          ht[i]->decodeNext(bitStream);
   112        });
   113      }
   114    }
   115    input.skipBytes(bitStream.getBufferPosition());
   116  }
