    96  void AbstractLJpegDecompressor::parseSOS() {
    97    if (!frame.initialized)
    98      ThrowRDE("Frame not yet initialized (SOF Marker not parsed)");
    99
   100    uint32 headerLength = input.getU16();
   101    if (headerLength != 3 + frame.cps * 2 + 3)
   102      ThrowRDE("Invalid SOS header length.");
   103
   104    uint32 soscps = input.getByte();
   105    if (frame.cps != soscps)
   106      ThrowRDE("Component number mismatch.");
   107
   108    for (uint32 i = 0; i < frame.cps; i++) {
   109      uint32 cs = input.getByte();
   110      uint32 td = input.getByte() >> 4;
   111
   112      if (td > 3 || !huff[td])
   113        ThrowRDE("Invalid Huffman table selection.");
   114
   115      int ciIndex = -1;
   116      for (uint32 j = 0; j < frame.cps; ++j) {
   117        if (frame.compInfo[j].componentId == cs)
   118          ciIndex = j;
   119      }
   120
   121      if (ciIndex == -1)
   122        ThrowRDE("Invalid Component Selector");
   123
   124      frame.compInfo[ciIndex].dcTblNo = td;
   125    }
   126
   127    // Get predictor, see table H.1 from the JPEG spec
   128    predictorMode = input.getByte();
   129    // The spec says predictoreMode is in [0..7], but Hasselblad uses '8'.
   130    if (predictorMode > 8)
   131      ThrowRDE("Invalid predictor mode.");
   132
   133    input.skipBytes(1);         // Se + Ah Not used in LJPEG
   134    Pt = input.getByte() & 0xf; // Point Transform
   135
   136    decodeScan();
   137  }
